from data import *
np.set_printoptions(precision=2,suppress=True,linewidth=250)
cosv=lambda u,v: float(u@v/np.linalg.norm(u)/np.linalg.norm(v))
TEMPL=['T1','T2','T3','T4','T5','T6']
j20=json.load(open('acts/trace_20.json')); z20=np.load('acts/trace_20.npz')
j21=json.load(open('acts/trace_21.json')); z21=np.load('acts/trace_21.npz')
def neg_other(M):
    # other-position negatives
    A=[];tok=[]
    for i,it in enumerate(j20):
        for p,pp in enumerate(it['positions']):
            if pp['reply_pos']>=3: A.append(z20[M][i,p]); tok.append(pp['token'])
    for i,it in enumerate(j21):
        for p,pp in enumerate(it['positions']): A.append(z21[M][i,p]); tok.append(pp['token'])
    return np.stack(A).astype(np.float32),tok
def pre_pos(M):
    A=[]
    for i,it in enumerate(j20):
        for p in (0,1): A.append(z20[M][i,p])
    return np.stack(A).astype(np.float32)
IS=[r for r in recs if r['pos']=='is']; SP=[r for r in recs if r['pos']=='sp']
def ridge_w(X,y,w,lam):
    # weighted ridge, dual form
    sw=np.sqrt(w); Xs=X*sw[:,None]; ys=y*sw
    K=Xs@Xs.T; n=len(y); al=np.linalg.solve(K+lam*np.trace(K)/n*np.eye(n),ys); return Xs.T@al
def reader(M,lam=0.03,exclude_t=None,sp_neg=True,w_other=1.0):
    tr=[r for r in IS if r['t']!=exclude_t]
    X=[X_of(tr,M)]; y=[np.array([0. if r['c']=='p' else 1. for r in tr])]
    # template-balanced weights
    cnt={t:sum(1 for r in tr if r['t']==t) for t in TEMPL}
    w=[np.array([len(tr)/len([t for t in cnt if cnt[t]>0])/cnt[r['t']] for r in tr])]
    No,_=neg_other(M); X.append(No); y.append(np.zeros(len(No))); w.append(np.full(len(No),w_other*len(tr)/len(No)))
    if sp_neg:
        Xs=X_of(SP,M); X.append(Xs); y.append(np.zeros(len(Xs))); w.append(np.full(len(Xs),0.5*len(tr)/len(Xs)))
    return ridge_w(np.concatenate(X),np.concatenate(y),np.concatenate(w),lam)
def dirs(M,exclude_t=None,word_only=True):
    Wm=Wof(M); ms={}
    for t in TEMPL:
        if t==exclude_t: continue
        D=[]
        for c1 in ('w','r'):
            P=pairs(lambda r: r['t']==t and r['pos']=='is' and (not r['num'] or not word_only),c1,'p')
            if P: D.append(X_of([a for a,b in P],M)-X_of([b for a,b in P],M))
        ms[t]=np.concatenate(D).mean(0)
    return ms   # in input space; output dir = Wm @ mean
