def neg_other_split(M):
    A=[];B=[]
    for i,it in enumerate(j20):
        for p,pp in enumerate(it['positions']):
            if pp['reply_pos']>=3: (A if i<8 else B).append(z20[M][i,p])
    for i,it in enumerate(j21):
        for p,pp in enumerate(it['positions']): (A if i<8 else B).append(z21[M][i,p])
    return np.stack(A).astype(np.float32),np.stack(B).astype(np.float32)
def reader2(M,lam,exclude_t=None,other=None,sp=None,w_other=1.0,w_sp=0.5):
    tr=[r for r in IS if r['t']!=exclude_t]
    X=[X_of(tr,M)]; y=[np.array([0. if r['c']=='p' else 1. for r in tr])]
    cnt={t:sum(1 for r in tr if r['t']==t) for t in TEMPL}
    nt=len([t for t in cnt if cnt[t]>0])
    w=[np.array([len(tr)/nt/cnt[r['t']] for r in tr])]
    if other is not None: X.append(other); y.append(np.zeros(len(other))); w.append(np.full(len(other),w_other*len(tr)/len(other)))
    if sp is not None: X.append(sp); y.append(np.zeros(len(sp))); w.append(np.full(len(sp),w_sp*len(tr)/len(sp)))
    return ridge_w(np.concatenate(X),np.concatenate(y),np.concatenate(w),lam)
